content.content:
1	package agentusage
2	
3	import (
4		"cmp"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"slices"
11		"strings"
12		"sync/atomic"
13		"time"
14	)
15	
16	// fileCursor is the read position of one transcript. Values only: no pointer
17	// except the immutable os.FileInfo.
18	type fileCursor struct {
19		path     string      // full path, never logged
20		name     string      // sanitized base name (FileIssue.File, TruncatedFiles)
21		agent    string      // key of the agent in a table: "" for the parent, else rank
22		label    string      // sanitized agent ID shown to the user; "" for the parent
23		rank     string      // position rank of the file (parentRank or transcriptRank)
24		id       os.FileInfo // from the open handle's Stat at the last read; nil before
25		offset   int64       // just past the last complete line folded in
26		size     int64       // file size at the last read
27		modTime  time.Time   // Lstat mtime at the last listing
28		skipFrom int64       // start of an oversized line still being written, or -1
29		tail     bool        // an incomplete line follows offset (TruncatedFiles)
30		issue    IssueKind   // state issue of the last read (D6), valid if hasIssue
31		issueOff int64
32		hasIssue bool
33	}
34	
35	// newFileCursor returns the cursor of a transcript not read yet.
36	func newFileCursor(path, name, agent, rank string) fileCursor {
37		return fileCursor{path: path, name: name, agent: agent, rank: rank, skipFrom: -1}
38	}
39	
40	// transcriptFile is what readFile needs from an open transcript; *os.File
41	// satisfies it.
42	type transcriptFile interface {
43		io.Reader
44		io.ReaderAt
45		io.Seeker
46		io.Closer
47		Stat() (os.FileInfo, error)
48	}
49	
50	// openTranscript opens a transcript through openPlain. A var so tests can
51	// count opens and bytes read.
52	var openTranscript = func(path string) (transcriptFile, error) {
53		f, err := openPlain(path, false)
54		if err != nil {
55			return nil, err
56		}
57		if f == nil {
58			return nil, errNotRegular
59		}
60		return f, nil
61	}
62	
63	// fileRead is the outcome of reading one file from its cursor.
64	type fileRead struct {
65		next  fileCursor
66		part  *table // lines folded from the new bytes; nil when nothing was read
67		reset bool   // not an append (D4): the caller restarts the whole session
68		err   error  // why the file could not be opened or read at all, if so
69	}
70	
71	// read reports whether the cursor has already read part of its file.
72	func (fc fileCursor) read() bool { return fc.offset > 0 || fc.skipFrom >= 0 || fc.id != nil }
73	
74	// quiet reports whether the file is, as far as Lstat can tell, exactly what the
75	// last read saw. A cursor holding a read error never is: the bytes between
76	// its offset and the failure must be read again.
77	func (fc fileCursor) quiet(li os.FileInfo) bool {
78		if fc.id == nil || (fc.hasIssue && fc.issue == IssueReadError) {
79			return false
80		}
81		return li.Size() == fc.size && os.SameFile(li, fc.id)
82	}
83	
84	// failRead is the outcome of a path that cannot be read: a reset when the file
85	// was read before (D4), else a state issue cleared by the next success (D6).
86	func failRead(fc fileCursor, err error) fileRead {
87		if fc.read() {
88			return fileRead{next: fc, reset: true, err: err}
89		}
90		fc.issue, fc.issueOff, fc.hasIssue = IssueOpenFailed, 0, true
91		return fileRead{next: fc, err: err}
92	}
93	
94	// isAppend reports whether the open file is the one fc read, only grown (D4).
95	func (fc fileCursor) isAppend(f transcriptFile, fi os.FileInfo) bool {
96		if (fc.id != nil && !os.SameFile(fi, fc.id)) || fi.Size() < fc.size {
97			return false
98		}
99		if fc.offset == 0 {
100			return true
101		}
102		var b [1]byte
103		n, _ := f.ReadAt(b[:], fc.offset-1)
104		return n == 1 && b[0] == '\n'
105	}
106	
107	// readFile reads what was appended to fc's file since fc. now clamps mtimes.
108	// It never follows a link and never opens a non-regular file.
109	func readFile(fc fileCursor, now time.Time) fileRead {
110		li, err := os.Lstat(fc.path)
111		if err != nil {
112			return failRead(fc, err)
113		}
114		if !li.Mode().IsRegular() {
115			return failRead(fc, errNotRegular)
116		}
117		fc.modTime = li.ModTime()
118		if fc.modTime.After(now) {
119			fc.modTime = now
120		}
121		if fc.quiet(li) {
122			return fileRead{next: fc}
123		}
124		f, err := openTranscript(fc.path)
125		if err != nil {
126			return failRead(fc, err)
127		}
128		defer func() { _ = f.Close() }()
129		fi, err := f.Stat()
130		if err != nil {
131			return failRead(fc, err)
132		}
133		if !fc.isAppend(f, fi) {
134			return fileRead{next: fc, reset: true}
135		}
136		return fc.scan(f, fi)
137	}
138	
139	// scan folds the lines past the cursor into a new table and returns the
140	// advanced cursor. A line held back is read again next time (D1); an
141	// oversized one still being written is resumed in skip mode (D2).
142	func (fc fileCursor) scan(f transcriptFile, fi os.FileInfo) fileRead {
143		start := fc.offset
144		if fc.skipFrom >= 0 {
145			start = fc.size
146		}
147		if _, err := f.Seek(start, io.SeekStart); err != nil {
148			return failRead(fc, err)
149		}
150		part := newTable()
151		res, err := scanFrom(f, start, fc.skipFrom, MaxLineBytes, func(line []byte, off int64) {
152			part.addLine(fc.agent, fc.name, pos{rank: fc.rank, off: off}, line)
153		})
154		for _, off := range res.OversizedAt {
155			part.addOversized(fc.name, pos{rank: fc.rank, off: off})
156		}
157		next := fc
158		next.id, next.size, next.skipFrom = fi, res.End, res.SkipFrom
159		next.offset, next.tail = res.Consumed, len(res.Tail) > 0
160		if fc.skipFrom >= 0 && res.Consumed == start {
161			next.offset = fc.offset // the oversized line has not ended yet
162		}
163		next.issue, next.issueOff, next.hasIssue = 0, 0, false
164		if err != nil {
165			next.issue, next.issueOff, next.hasIssue = IssueReadError, next.offset, true
166		}
167		return fileRead{next: next, part: part}
168	}
169	
170	// ErrStaleDelta is returned by Apply for a delta that was not read from the
171	// aggregate's current cursor. The aggregate is unchanged; read again from
172	// Cursor().
173	var ErrStaleDelta = errors.New("agentusage: delta does not follow the aggregate's cursor")
174	
175	// readMetaFile reads one meta file; a var so tests can count meta reads (D7).
176	// The session reader goes through it.
177	var readMetaFile = readMeta
178	
179	// timeNow is time.Now; a var for tests.
180	var timeNow = time.Now
181	
182	// aggregateIDs hands out the identity of each Aggregate (D9).
183	var aggregateIDs atomic.Uint64
184	
185	// metaCursor is the last listing of one sub-agent's meta file and what was
186	// read from it. Values only, so a cursor stays a plain copyable value.
187	type metaCursor struct {
188		rank       string // rank of the sub-agent's transcript
189		path       string // "" when absent
190		size       int64
191		modTime    time.Time
192		unreadable bool
193		typ        string
194		state      State
195		depth      int
196	}
197	
198	// sameResult reports whether o tells the same story as m: Lstat details such
199	// as the mtime are not part of it.
200	func (m metaCursor) sameResult(o metaCursor) bool {
201		return m.rank == o.rank && (m.path == "") == (o.path == "") && m.unreadable == o.unreadable &&
202			m.typ == o.typ && m.state == o.state && m.depth == o.depth
203	}
204	
205	// unchangedSince reports whether the file Lstat described by fi is the one m
206	// was read from.
207	func (m metaCursor) unchangedSince(path string, fi os.FileInfo) bool {
208		return fi != nil && m.path == path && m.size == fi.Size() && m.modTime.Equal(fi.ModTime())
209	}
210	
211	// Cursor records how far each file of one session has been read. It is a
212	// plain value: copying it is safe and ReadDelta never mutates it. It holds
213	// full paths, so it must never be logged; String and GoString redact them.
214	type Cursor struct {
215		parent string // parent transcript path
216		id     uint64 // identity of the aggregate it came from
217		seq    uint64 // number of deltas applied when it was taken
218		fresh  bool   // nothing applied yet, or rewound: the next delta is Full
219		files  []fileCursor
220		metas  []metaCursor
221	}
222	
223	// Rewound returns c with every position cleared, keeping its identity: the
224	// next ReadDelta reads every file from the start and returns a Full delta.
225	func (c Cursor) Rewound() Cursor {
226		files := make([]fileCursor, len(c.files))
227		for i, fc := range c.files {
228			files[i] = newFileCursor(fc.path, fc.name, fc.agent, fc.rank)
229			files[i].label = fc.label
230		}
231		c.files, c.metas, c.fresh = files, nil, true
232		return c
233	}
234	
235	// String redacts the paths the cursor holds.
236	func (c Cursor) String() string { return fmt.Sprintf("agentusage.Cursor{files: %d}", len(c.files)) }
237	
238	// GoString redacts the paths the cursor holds.
239	func (c Cursor) GoString() string { return c.String() }
240	
241	// Delta is what ReadDelta found since a Cursor: the new complete lines of each
242	// file, already deduplicated, the files that appeared, the meta files that
243	// changed, and the positions to resume from. Paths live in unexported fields
244	// and are never printed.
245	type Delta struct {
246		valid     bool   // false for the zero Delta, which was never read
247		id, seq   uint64 // the cursor it was read from
248		full      bool
249		changed   bool
250		sessionID string
251		files     []fileCursor
252		metas     []metaCursor
253		part      *table
254		parentErr error     // why the parent could not be opened, for ParseSession
255		read      time.Time // when it was read: mtimes are clamped to it
256	}
257	
258	// Full reports whether the delta was read from the start of every file (first
259	// read, Rewound cursor, or a change that was not an append).
260	func (d Delta) Full() bool { return d.full }
261	
262	// Empty reports whether nothing changed: no new complete line, no file added
263	// or gone, no meta change, no change of a file's end-of-file state (an
264	// incomplete last line appearing or disappearing) or of its read issue. A
265	// held-back line that only grows, a persistent issue, or an mtime that alone
266	// moved do not count.
267	func (d Delta) Empty() bool { return !d.changed }
268	
269	// String shows counts only.
270	func (d Delta) String() string {
271		return fmt.Sprintf("agentusage.Delta{full: %t, empty: %t, files: %d}", d.full, d.Empty(), len(d.files))
272	}
273	
274	// GoString shows counts only.
275	func (d Delta) GoString() string { return d.String() }
276	
277	// Aggregate is a session's usage built from successive deltas. It is not safe
278	// for concurrent use: one goroutine (Bubble Tea's Update) owns it.
279	type Aggregate struct {
280		parent    string
281		id, seq   uint64
282		fresh     bool
283		sessionID string
284		files     []fileCursor // parent first, then sub-agents by rank
285		metas     []metaCursor
286		t         *table
287		lastMod   time.Time // newest mtime seen by the last non-empty delta, see Activity
288	}
289	
290	// String shows counts only: an Aggregate holds paths, and the value receiver
291	// also covers a dereferenced *a.
292	func (a Aggregate) String() string {
293		return fmt.Sprintf("agentusage.Aggregate{files: %d, applied: %d}", len(a.files), a.seq)
294	}
295	
296	// GoString shows counts only.
297	func (a Aggregate) GoString() string { return a.String() }
298	
299	// NewAggregate starts an empty aggregate for the session whose parent
300	// transcript is parentTranscript (<dir>/<uuid>.jsonl). It does no I/O.
301	func NewAggregate(parentTranscript string) *Aggregate {
302		base := filepath.Base(parentTranscript)
303		return &Aggregate{
304			parent:    parentTranscript,
305			id:        aggregateIDs.Add(1),
306			fresh:     true,
307			sessionID: sanitizeLabel(strings.TrimSuffix(base, transcriptExt)),
308			files:     []fileCursor{newFileCursor(parentTranscript, sanitizeLabel(base), "", parentRank)},
309			t:         newTable(),
310		}
311	}
312	
313	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
314	func (a *Aggregate) Cursor() Cursor {
315		return Cursor{
316			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
317			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
318		}
319	}
320	
321	// Apply folds d in, or replaces everything with it when d.Full(). It returns
322	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
323	// takes ownership of d.
324	func (a *Aggregate) Apply(d Delta) error {
325		if !d.valid || d.id != a.id || d.seq != a.seq {
326			return ErrStaleDelta
327		}
328		switch {
329		case d.full:
330			a.t = boundedTable(d.part)
331		case d.part != nil:
332			a.t.mergeCapped(d.part)
333		}
334		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
335		if d.changed {
336			a.lastMod = newestMod(d)
337		}
338		a.fresh = false
339		a.seq++
340		return nil
341	}
342	
343	// boundedTable returns part, or a copy of it holding at most maxNoIDEntries
344	// entries without a message id.
345	func boundedTable(part *table) *table {
346		if part == nil {
347			return newTable()
348		}
349		if part.noID <= maxNoIDEntries {
350			return part
351		}
352		t := newTable()
353		t.mergeCapped(part)
354		return t
355	}
356	
357	// Usage returns the session's usage so far, same shape and rules as
358	// ParseSession; the result shares no memory with the aggregate.
359	func (a *Aggregate) Usage() Usage {
360		agents := []Agent{{Main: true, State: StateUnknown}}
361		var diag Diagnostics
362		var truncated []string
363		var issues []issueAt
364		metaOf := make(map[string]metaCursor, len(a.metas))
365		for _, m := range a.metas {
366			metaOf[m.rank] = m
367		}
368		for _, fc := range a.files {
369			if fc.tail {
370				truncated = append(truncated, fc.name)
371			}
372			if fc.hasIssue {
373				fi := FileIssue{File: fc.name, Offset: fc.issueOff, Kind: fc.issue}
374				issues = append(issues, issueAt{p: pos{rank: fc.rank, off: fc.issueOff}, fi: fi})
375			}
376			if fc.rank != parentRank {
377				agents = append(agents, subAgent(fc, metaOf[fc.rank], &diag))
378			}
379		}
380		agents, diag2, versions := a.t.finishWith(agents, issues)
381		diag2.MetaMissing, diag2.MetaUnreadable, diag2.TruncatedFiles = diag.MetaMissing, diag.MetaUnreadable, truncated
382		return Usage{SessionID: a.sessionID, Agents: agents, Versions: versions, Diagnostics: diag2}
383	}
384	
385	// subAgent builds a sub-agent's identity from its meta cursor, counting a
386	// missing or unreadable meta file in diag.
387	func subAgent(fc fileCursor, m metaCursor, diag *Diagnostics) Agent {
388		ag := Agent{ID: fc.label, key: fc.rank}
389		switch {
390		case m.path == "":
391			diag.MetaMissing++
392		case m.unreadable:
393			diag.MetaUnreadable++
394		default:
395			ag.Type, ag.State, ag.SpawnDepth = m.typ, m.state, m.depth
396		}
397		return ag
398	}
399	
400	// ReadDelta lists the session again (parent, subagents/, meta files, Lstat
401	// only) and reads what was appended since c. Files whose size did not change
402	// are not opened. It fails only if the session cannot be listed; errors name
403	// base names only, and on error there is nothing to apply. A parent that is
404	// missing, unreadable or not a regular file is not an error: the delta then
405	// carries an IssueOpenFailed on the parent (Full at tick 0, then Empty while
406	// it persists), which the caller must detect through the parent's FileIssue.
407	//
408	// Declared oracle gap (meta files): a meta file that cannot be read (chmod 000)
409	// counts as MetaUnreadable here, whereas ParseSession(LocateSession) counts it
410	// MetaMissing. Meta files are compared by Lstat size and mtime (D7), so an
411	// unreadable meta stays so after chmod +r until it is rewritten.
412	func ReadDelta(c Cursor) (Delta, error) {
413		files, infos, err := listForPoll(c.parent)
414		if err != nil {
415			return Delta{}, err
416		}
417		return readSession(files, infos, c, timeNow()), nil
418	}
419	
420	// listForPoll lists the session like LocateSession, with meta presence from
421	// Lstat only (D7), and returns the Lstat result of each meta file found.
422	func listForPoll(parent string) (SessionFiles, map[string]os.FileInfo, error) {
423		infos := map[string]os.FileInfo{}
424		files, err := locateSession(parent, func(path string) bool {
425			fi, err := os.Lstat(path)
426			if err != nil || !fi.Mode().IsRegular() {
427				return false
428			}
429			infos[path] = fi
430			return true
431		})
432		return files, infos, err
433	}
434	
435	// target is one transcript of a listing, with its meta file ("" if absent).
436	type target struct {
437		fc   fileCursor
438		meta string
439	}
440	
441	// sessionTargets turns a listing into fresh cursors: the parent first, then
442	// the sub-agents in rank order, which is the order ParseSession reads them.
443	func sessionTargets(files SessionFiles) []target {
444		out := []target{{fc: newFileCursor(files.Parent, sanitizeLabel(filepath.Base(files.Parent)), "", parentRank)}}
445		for _, sa := range files.SubAgents {
446			id := sanitizeLabel(sa.ID)
447			name := sanitizeLabel(filepath.Base(sa.Transcript))
448			rank := transcriptRank(id, name, sa.ID, sa.Transcript)
449			fc := newFileCursor(sa.Transcript, name, rank, rank)
450			fc.label = id
451			out = append(out, target{fc: fc, meta: sa.Meta})
452		}
453		slices.SortFunc(out[1:], func(a, b target) int { return cmp.Compare(a.fc.rank, b.fc.rank) })
454		return out
455	}
456	
457	// readSession reads the files of a listing from c. A change that is not an
458	// append (D4) restarts every file from the start and the delta is Full.
459	// ParseSession passes a fresh cursor and no meta Lstat information.
460	func readSession(files SessionFiles, infos map[string]os.FileInfo, c Cursor, now time.Time) Delta {
461		targets := sessionTargets(files)
462		full := c.fresh
463		p, ok := readTargets(targets, c, now)
464		if !ok {
465			c, full = c.Rewound(), true
466			// ok is true by construction: a rewound cursor knows no file, so no
467			// file can ask for another restart.
468			p, _ = readTargets(targets, c, now)
469		}
470		metas, metaChanged := readMetas(targets[1:], infos, c)
471		return Delta{
472			valid: true, id: c.id, seq: c.seq, full: full,
473			changed:   full || p.changed || metaChanged,
474			sessionID: sanitizeLabel(files.ID),
475			files:     p.files, metas: metas, part: p.part, parentErr: p.parentErr, read: now,
476		}
477	}
478	
479	// sessionPass is the outcome of one pass over the transcripts.
480	type sessionPass struct {
481		files     []fileCursor
482		part      *table
483		changed   bool
484		parentErr error
485	}
486	
487	// readTargets reads every target from its cursor in c, or from the start when
488	// c does not know it. ok is false when a file asks for a restart (D4): a
489	// file read before is gone, or was not simply appended to.
490	func readTargets(targets []target, c Cursor, now time.Time) (sessionPass, bool) {
491		prior := make(map[string]fileCursor, len(c.files))
492		for _, fc := range c.files {
493			prior[fc.rank] = fc
494		}
495		var p sessionPass
496		for _, tg := range targets {
497			fc, had := prior[tg.fc.rank]
498			delete(prior, tg.fc.rank)
499			if !had {
500				fc, p.changed = tg.fc, true
501			}
502			fr := readFile(fc, now)
503			if fr.reset {
504				return sessionPass{}, false
505			}
506			if fr.next.rank == parentRank && fr.err != nil {
507				p.parentErr = fr.err
508			}
509			p.changed = p.changed || fr.part.hasLines() || fc.issueState() != fr.next.issueState() ||
510				fc.tail != fr.next.tail
511			p.files = append(p.files, fr.next)
512			p.addPart(fr.part)
513		}
514		for _, gone := range prior {
515			if gone.read() {
516				return sessionPass{}, false
517			}
518			p.changed = true
519		}
520		return p, true
521	}
522	
523	// addPart folds the lines of one file into the pass, spilling no-id lines past
524	// maxNoIDEntries like a sequential read does (totals stay exact).
525	func (p *sessionPass) addPart(part *table) {
526		switch {
527		case part == nil:
528		case p.part == nil:
529			p.part = part
530		default:
531			p.part.mergeCapped(part) // keeps the pass within the no-id bound across files
532		}
533	}
534	
535	// issueState is what a cursor says about its last read, for comparisons.
536	type issueState struct {
537		has  bool
538		kind IssueKind
539		off  int64
540	}
541	
542	func (fc fileCursor) issueState() issueState {
543		return issueState{has: fc.hasIssue, kind: fc.issue, off: fc.issueOff}
544	}
545	
546	// readMetas returns the meta cursors of the sub-agents in targets, reading a
547	// meta file only when its Lstat size or mtime differs from c's (D7), and
548	// whether any of them tells something new. An unreadable meta file is
549	// MetaUnreadable here but MetaMissing for ParseSession(LocateSession): a
550	// declared oracle gap, see ReadDelta.
551	func readMetas(subs []target, infos map[string]os.FileInfo, c Cursor) ([]metaCursor, bool) {
552		prior := make(map[string]metaCursor, len(c.metas))
553		for _, m := range c.metas {
554			prior[m.rank] = m
555		}
556		out := make([]metaCursor, 0, len(subs))
557		changed := false
558		for _, tg := range subs {
559			m := nextMeta(tg, infos, prior)
560			old, had := prior[m.rank]
561			changed = changed || !had || !old.sameResult(m)
562			out = append(out, m)
563		}
564		return out, changed
565	}
566	
567	// nextMeta returns the meta cursor of one sub-agent: the prior one when its
568	// file did not change, else a fresh read through readMetaFile.
569	func nextMeta(tg target, infos map[string]os.FileInfo, prior map[string]metaCursor) metaCursor {
570		m := metaCursor{rank: tg.fc.rank}
571		if tg.meta == "" {
572			return m
573		}
574		m.path = tg.meta
575		fi := infos[tg.meta]
576		if fi != nil {
577			m.size, m.modTime = fi.Size(), fi.ModTime()
578		}
579		if old, ok := prior[m.rank]; ok && old.unchangedSince(tg.meta, fi) {
580			return old
581		}
582		md, err := readMetaFile(tg.meta)
583		if err != nil {
584			m.unreadable = true
585			return m
586		}
587		m.typ, m.state, m.depth = md.AgentType, md.state(), md.SpawnDepth
588		return m
589	}
590	
591	// newestMod returns the newest mtime among the files and metas of d, clamped
592	// to the time d was read.
593	func newestMod(d Delta) time.Time {
594		var newest time.Time
595		for _, fc := range d.files {
596			if fc.modTime.After(newest) {
597				newest = fc.modTime
598			}
599		}
600		for _, m := range d.metas {
601			if m.modTime.After(newest) {
602				newest = m.modTime
603			}
604		}
605		if newest.After(d.read) {
606			newest = d.read
607		}
608		return newest
609	}
610	
611	// Activity tells a poller when a session has gone quiet. It holds times and
612	// counts only, never a path.
613	type Activity struct {
614		// LastChange is the newest mtime among the parent, the sub-agents and the
615		// metas as of the last read that found a change, capped at that read's
616		// time. Zero before the first Apply. An empty delta does not advance it.
617		LastChange time.Time
618		// Unfinished counts sub-agents whose meta says finished: false.
619		Unfinished int
620		// unreadable is set when the parent transcript could not be opened.
621		unreadable bool
622	}
623	
624	// Settled reports whether polling can stop: something was applied, the parent
625	// is readable, no sub-agent is unfinished, and nothing changed for at least
626	// quiet before now.
627	func (a Activity) Settled(now time.Time, quiet time.Duration) bool {
628		return !a.LastChange.IsZero() && !a.unreadable && a.Unfinished == 0 && now.Sub(a.LastChange) >= quiet
629	}
630	
631	// Activity returns what the reads applied so far say about the session's life.
632	func (a *Aggregate) Activity() Activity {
633		act := Activity{LastChange: a.lastMod}
634		for _, m := range a.metas {
635			if m.path != "" && !m.unreadable && m.state == StateUnfinished {
636				act.Unfinished++
637			}
638		}
639		if len(a.files) > 0 {
640			p := a.files[0]
641			act.unreadable = p.hasIssue && p.issue == IssueOpenFailed
642		}
643		return act
644	}
645

