13	// under -race: one goroutine owns the Aggregate (ReadDelta + Apply), another
14	// appends to the transcripts mid-line, others read copies.
15	
16	// writerChunks builds the bytes a writer appends: whole lines, cut at
17	// arbitrary points (also inside a CRLF), so a reader often sees a torn line.
18	func writerChunks(prefix string, lines int) [][]byte {
19		var all bytes.Buffer
20		for i := range lines {
21			id := fmt.Sprintf("%s-%d", prefix, i%7)
22			all.Write(msgLine(id, "claude-r", "end_turn", int64(i), 2, 3, 4))
23			if i%3 == 0 {
24				all.WriteString("\r\n")
25			} else {
26				all.WriteByte('\n')
27			}
28			if i%5 == 0 {
29				all.WriteString("not json {{\n")
30			}
31		}
32		data := all.Bytes()
