package agentusage

import (
	"bytes"
	"fmt"
	"os"
	"sync"
	"sync/atomic"
	"testing"
)

// Concurrency tests of the incremental reader (DEVDESK-44 step 6). Run them
// under -race: one goroutine owns the Aggregate (ReadDelta + Apply), another
// appends to the transcripts mid-line, others read copies.

// writerChunks builds the bytes a writer appends: whole lines, cut at
// arbitrary points (also inside a CRLF), so a reader often sees a torn line.
func writerChunks(prefix string, lines int) [][]byte {
	var all bytes.Buffer
	for i := range lines {
		id := fmt.Sprintf("%s-%d", prefix, i%7)
		all.Write(msgLine(id, "claude-r", "end_turn", int64(i), 2, 3, 4))
		if i%3 == 0 {
			all.WriteString("\r\n")
		} else {
			all.WriteByte('\n')
		}
		if i%5 == 0 {
			all.WriteString("not json {{\n")
		}
	}
	data := all.Bytes()
	var out [][]byte
	for off, step := 0, 1; off < len(data); step = step%37 + 5 {
		end := min(off+step, len(data))
		out = append(out, data[off:end])
		off = end
	}
	return out
}

func appendRaw(path string, data []byte) error {
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	if _, err := f.Write(data); err != nil {
		_ = f.Close()
		return err
	}
	return f.Close()
}

func TestConcurrentWriterReaderMatchesParse(t *testing.T) {
	s := newSess(t)
	if err := os.MkdirAll(s.subDir(), 0o700); err != nil {
		t.Fatal(err)
	}
	s.put(s.parent(), nil) // the parent transcript exists before the first read
	a := NewAggregate(s.parent())

	parentChunks := writerChunks("p", 60)
	subChunks := writerChunks("s", 60)
	var wg sync.WaitGroup
	var done atomic.Bool
	var werr atomic.Value

	wg.Add(1)
	go func() {
		defer wg.Done()
		defer done.Store(true)
		for i := range max(len(parentChunks), len(subChunks)) {
			if i < len(parentChunks) {
				if err := appendRaw(s.parent(), parentChunks[i]); err != nil {
					werr.Store(err)
					return
				}
			}
			if i < len(subChunks) {
				if err := appendRaw(s.sub("a1"), subChunks[i]); err != nil {
					werr.Store(err)
					return
				}
			}
		}
	}()

	// Readers of copies: they never touch the Aggregate itself; the owner
	// publishes copies through a mutex.
	var mu sync.Mutex
	var curCopy Cursor
	var useCopy Usage
	publish := func() {
		c, u := a.Cursor(), a.Usage()
		mu.Lock()
		curCopy, useCopy = c, u
		mu.Unlock()
	}
	var rwg sync.WaitGroup
	var stop atomic.Bool
	for range 3 {
		rwg.Add(1)
		go func() {
			defer rwg.Done()
			for !stop.Load() {
				mu.Lock()
				c, u := curCopy, useCopy
				mu.Unlock()
				_ = c.String()
				_ = u.Total() // read-only: the published copy is shared by the readers
				_ = u.Diagnostics.Degraded()
			}
		}()
	}

	for !done.Load() {
		readApply(t, a)
		publish()
	}
	wg.Wait()
	if err, _ := werr.Load().(error); err != nil {
		t.Fatalf("writer: %v", err)
	}
	readApply(t, a)
	readApply(t, a)
	publish()
	stop.Store(true)
	rwg.Wait()

	assertMatchesParse(t, a, s)
}

// Mutating what Usage() and Cursor() return does not reach the aggregate.
func TestConcurrentCopiesShareNoMemory(t *testing.T) {
	s := newSess(t)
	s.put(s.parent(), append(msgLine("m1", "claude-r", "end_turn", 1, 2, 3, 4), '\n'))
	s.put(s.sub("a1"), append(msgLine("m2", "claude-r", "end_turn", 1, 2, 3, 4), '\n'))
	a := NewAggregate(s.parent())
	readApply(t, a)
	want := a.Usage()

	var wg sync.WaitGroup
	for range 4 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 50 {
				u := a.Usage()
				for i := range u.Agents {
					u.Agents[i].Messages += 100
					u.Agents[i].Models = append(u.Agents[i].Models, "x")
				}
				u.Versions = append(u.Versions, "v")
				u.Diagnostics.TruncatedFiles = append(u.Diagnostics.TruncatedFiles, "x")
				c := a.Cursor()
				if len(c.files) > 0 {
					c.files[0].offset += 99
				}
				c.files = append(c.files, fileCursor{})
			}
		}()
	}
	wg.Wait()
	assertSameUsage(t, a.Usage(), want)
	readApply(t, a)
	assertMatchesParse(t, a, s)
}

package agentusage

import (
	"bytes"
	"strings"
	"testing"
)

// fuzzMaxInput keeps one fuzz execution fast; MaxLineBytes-sized seeds are
// built by the seed loop below and are exempt (they are not mutated).
const fuzzMaxInput = 64 << 10

// FuzzIncrementalMatchesFull: the input is cut into chunks appended one by
// one to a parent and a sub-agent transcript, with one ReadDelta+Apply after
// each; the final aggregate must equal ParseSession on the final files, and
// nothing may panic.
func FuzzIncrementalMatchesFull(f *testing.F) {
	ok := string(msgLine("m1", "claude-f", "end_turn", 1, 2, 3, 4)) + "\n"
	ok2 := string(msgLine("m1", "claude-f", "tool_use", 5, 6, 7, 8)) + "\n"
	f.Add([]byte(ok+ok2), []byte(ok), uint8(7))
	f.Add([]byte(strings.ReplaceAll(ok+ok2, "\n", "\r\n")), []byte(ok), uint8(1))
	f.Add([]byte(ok[:len(ok)/2]), []byte(ok+ok[:10]), uint8(3))
	f.Add([]byte(`{"message":{"content":"héllo`+"\xe2\x82"), []byte(ok), uint8(2)) // UTF-8 cut mid-rune
	f.Add([]byte(ok+"not json {{{\n\n"+ok2), []byte("[]\n\"x\"\n123\n"), uint8(5))
	f.Add([]byte(ok), []byte(ok2), uint8(0))
	f.Add(bytes.Repeat([]byte("a"), MaxLineBytes+10), []byte(ok), uint8(200)) // over-long line

	f.Fuzz(func(t *testing.T, parent, sub []byte, step uint8) {
		if len(parent) > fuzzMaxInput && len(parent) <= MaxLineBytes {
			t.Skip("input too large")
		}
		if len(sub) > fuzzMaxInput {
			t.Skip("input too large")
		}
		s := newSess(t)
		size := int(step)%64 + 1
		if step == 0 {
			size = 0 // line by line
		}
		s.put(s.parent(), nil) // the parent transcript exists before the first read
		a := NewAggregate(s.parent())
		srcs := []*src{{path: s.parent(), data: parent}, {path: s.sub("f1"), data: sub}}
		offs := make([]int, len(srcs))
		readApply(t, a)
		for pending := true; pending; {
			pending = false
			for i, sr := range srcs {
				if offs[i] >= len(sr.data) {
					continue
				}
				pending = true
				end := nextChunk(sr.data, offs[i], size)
				if size > 0 && len(sr.data) > 4096 {
					end = nextChunk(sr.data, offs[i], max(size, len(sr.data)/16))
				}
				s.add(sr.path, sr.data[offs[i]:end])
				offs[i] = end
				readApply(t, a)
			}
		}
		readApply(t, a)
		assertMatchesParse(t, a, s)
	})
}

